import {squadPlan,saleSquadImpact} from './squad-planner.js';
import {escapeHtml as esc} from './ui-kit.js';
import {availabilityText} from './career-availability.js';
import {viewButton as v} from './manager-ui-kit.js';
const status={missing:'Missing cover',thin:'Thin cover',covered:'Covered'};
export function renderSquadPlan(c,{compact=false}={}){
 const plan=squadPlan(c);if(!plan)return '';
 const rows=compact?plan.positions.filter(p=>p.status!=='covered').sort((a,b)=>Number(b.status==='missing')-Number(a.status==='missing')).slice(0,3):plan.positions;
 return `<section class="card mgr-card mgr-squad-plan" aria-label="Squad planner"><span class="eyebrow">SQUAD PLANNER · ${esc(plan.formation)}</span><h2>${plan.canFieldXI?'Plan your depth':'Cover needed before kickoff'}</h2><p>${plan.available} available / ${plan.size} registered · next fixture ${esc(plan.date)}. ${plan.canFieldXI?'An eligible XI can be assigned.':'Unfilled natural positions: '+esc(plan.missing.join(', '))+'.'}</p><div class="mgr-plan-grid">${rows.map(p=>`<article class="mgr-plan-position ${p.status}" data-plan-position="${p.position}"><div class="mgr-plan-heading"><h3>${p.position}</h3><span>${status[p.status]}</span></div><p>${p.demand} starting place${p.demand===1?'':'s'} · ${p.available.length} available · ${p.kind==='depth'?'Recruitment: depth':'Recruitment: upgrade only'}</p>${compact?'':`<p><strong>Selected:</strong> ${p.starters.map(id=>esc(plan.players.find(q=>q.id===id)?.name||'Unfilled')).join(', ')||'Unfilled'}</p><details><summary>Eligible players & availability</summary><ul>${p.players.map(q=>`<li><strong>${esc(q.name)}</strong><small>${q.rating} OVR · ${!q.contracted?'Contract ends before fixture':q.absence?esc(availabilityText(q.absence)):Math.round(q.energy)+'% energy'}${p.starters.includes(q.id)?' · selected':''}</small></li>`).join('')}</ul></details>`}${p.status!=='covered'?v('Find '+p.position+' cover','recruit-position',p.position):''}</article>`).join('')||'<p>Every position has an independently assignable reserve.</p>'}</div><p class="stat-foot">Versatile players appear in each eligible position. Cover checks assign each person once across the whole XI plus one reserve; reserves across different positions are shared. ${compact?v('Open squad planner','squad-tab','planning'):''}</p></section>`;
}
export function renderSaleImpact(c,id){
 const impact=saleSquadImpact(c,id);if(!impact)return '';
 return `<section class="mgr-sale-impact" aria-label="Sale squad impact"><h3>Squad after this sale</h3><p>${impact.after.size} registered · ${impact.after.available} available · ${impact.after.canFieldXI?'eligible XI possible':'current formation cannot be filled'}.</p>${impact.starter?'<p>Move this starter to the bench and select a replacement before accepting.</p>':''}${impact.warnings.length?`<ul>${impact.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:'<p>Positional reserve cover is retained for the next fixture.</p>'}<p class="stat-foot">Preview uses current contracts and availability for the next fixture. Shared reserves and future absences can change cover. Existing legal-sale checks still apply.</p></section>`;
}
